arguments.command:
cd /src/php-src && apply_patch <<'PATCH'
*** Begin Patch
*** Update File: ext/hash/hash_xxhash.c
@@
 #include "php_hash.h"
 #include "php_hash_xxhash.h"
+
+/*
+ * xxHash contexts can be (un)serialized using php_hash_serialize_spec().
+ * The spec only validates the overall context size, not the internal
+ * invariants expected by xxhash.h. In particular, XXH{32,64}_state_t::memsize
+ * is used to compute memcpy lengths and offsets into fixed-size buffers
+ * (mem32/mem64). If memsize is attacker-controlled (via unserialize) and
+ * exceeds the buffer size, calculations such as (32 - memsize) underflow and
+ * lead to huge memcpy() calls (heap-buffer-overflow).
+ *
+ * To keep changes minimal and local, provide xxhash-specific unserializers
+ * which validate memsize before the context can be used.
+ */
+
+static int php_hash_xxh32_unserialize(php_hashcontext_object *hash, zend_long magic, const zval *zv)
+{
+	int ret;
+	PHP_XXH32_CTX *ctx = (PHP_XXH32_CTX *) hash->context;
+
+	if (magic != PHP_HASH_SERIALIZE_MAGIC_SPEC) {
+		return FAILURE;
+	}
+
+	ret = php_hash_unserialize_spec(hash, zv, PHP_XXH32_SPEC);
+	if (ret != SUCCESS) {
+		return ret;
+	}
+
+	/* XXH32_state_t::memsize is a byte count into mem32 (16 bytes). */
+	if ((size_t) ctx->s.memsize > sizeof(ctx->s.mem32)) {
+		return FAILURE;
+	}
+
+	return SUCCESS;
+}
+
+static int php_hash_xxh64_unserialize(php_hashcontext_object *hash, zend_long magic, const zval *zv)
+{
+	int ret;
+	PHP_XXH64_CTX *ctx = (PHP_XXH64_CTX *) hash->context;
+
+	if (magic != PHP_HASH_SERIALIZE_MAGIC_SPEC) {
+		return FAILURE;
+	}
+
+	ret = php_hash_unserialize_spec(hash, zv, PHP_XXH64_SPEC);
+	if (ret != SUCCESS) {
+		return ret;
+	}
+
+	/* XXH64_state_t::memsize is a byte count into mem64 (32 bytes). */
+	if ((size_t) ctx->s.memsize > sizeof(ctx->s.mem64)) {
+		return FAILURE;
+	}
+
+	return SUCCESS;
+}
@@
 const php_hash_ops php_hash_xxh32_ops = {
 	"xxh32",
 	(php_hash_init_func_t) PHP_XXH32Init,
 	(php_hash_update_func_t) PHP_XXH32Update,
 	(php_hash_final_func_t) PHP_XXH32Final,
 	(php_hash_copy_func_t) PHP_XXH32Copy,
 	php_hash_serialize,
-	php_hash_unserialize,
+	php_hash_xxh32_unserialize,
 	PHP_XXH32_SPEC,
 	4,
 	4,
 	sizeof(PHP_XXH32_CTX),
 	0
 };
@@
 const php_hash_ops php_hash_xxh64_ops = {
 	"xxh64",
 	(php_hash_init_func_t) PHP_XXH64Init,
 	(php_hash_update_func_t) PHP_XXH64Update,
 	(php_hash_final_func_t) PHP_XXH64Final,
 	(php_hash_copy_func_t) PHP_XXH64Copy,
 	php_hash_serialize,
-	php_hash_unserialize,
+	php_hash_xxh64_unserialize,
 	PHP_XXH64_SPEC,
 	8,
 	8,
 	sizeof(PHP_XXH64_CTX),
 	0
 };
*** End Patch
PATCH

cd /src/php-src && python3 - <<'PY'
from pathlib import Path
path = Path('ext/hash/hash_xxhash.c')
data = path.read_text(encoding='utf-8')
needle = '#include "php_hash.h"\n#include "php_hash_xxhash.h"\n'
if needle not in data:
    raise SystemExit('unexpected include header')
insert = needle + "\n" + r'''/*
 * xxHash contexts can be (un)serialized using php_hash_serialize_spec().
 * The spec only validates the overall context size, not the internal
 * invariants expected by xxhash.h. In particular, XXH{32,64}_state_t::memsize
 * is used to compute memcpy lengths and offsets into fixed-size buffers
 * (mem32/mem64). If memsize is attacker-controlled (via unserialize) and
 * exceeds the buffer size, calculations such as (32 - memsize) underflow and
 * lead to huge memcpy() calls (heap-buffer-overflow).
 *
 * Provide xxhash-specific unserializers which validate memsize before the
 * context can be used.
 */

static int php_hash_xxh32_unserialize(php_hashcontext_object *hash, zend_long magic, const zval *zv)
{
	int ret;
	PHP_XXH32_CTX *ctx = (PHP_XXH32_CTX *) hash->context;

	if (magic != PHP_HASH_SERIALIZE_MAGIC_SPEC) {
		return FAILURE;
	}

	ret = php_hash_unserialize_spec(hash, zv, PHP_XXH32_SPEC);
	if (ret != SUCCESS) {
		return ret;
	}

	/* XXH32_state_t::memsize is a byte count into mem32 (16 bytes). */
	if ((size_t) ctx->s.memsize > sizeof(ctx->s.mem32)) {
		return FAILURE;
	}

	return SUCCESS;
}

static int php_hash_xxh64_unserialize(php_hashcontext_object *hash, zend_long magic, const zval *zv)
{
	int ret;
	PHP_XXH64_CTX *ctx = (PHP_XXH64_CTX *) hash->context;

	if (magic != PHP_HASH_SERIALIZE_MAGIC_SPEC) {
		return FAILURE;
	}

	ret = php_hash_unserialize_spec(hash, zv, PHP_XXH64_SPEC);
	if (ret != SUCCESS) {
		return ret;
	}

	/* XXH64_state_t::memsize is a byte count into mem64 (32 bytes). */
	if ((size_t) ctx->s.memsize > sizeof(ctx->s.mem64)) {
		return FAILURE;
	}

	return SUCCESS;
}

'''
# Only insert once
if 'php_hash_xxh64_unserialize' not in data:
    data = data.replace(needle, insert)

# Replace unserialize function pointers in ops
old32 = '\tphp_hash_serialize,\n\tphp_hash_unserialize,\n\tPHP_XXH32_SPEC,'
new32 = '\tphp_hash_serialize,\n\tphp_hash_xxh32_unserialize,\n\tPHP_XXH32_SPEC,'
if old32 not in data:
    raise SystemExit('xxh32 ops pattern not found')
data = data.replace(old32, new32, 1)

old64 = '\tphp_hash_serialize,\n\tphp_hash_unserialize,\n\tPHP_XXH64_SPEC,'
new64 = '\tphp_hash_serialize,\n\tphp_hash_xxh64_unserialize,\n\tPHP_XXH64_SPEC,'
if old64 not in data:
    raise SystemExit('xxh64 ops pattern not found')
data = data.replace(old64, new64, 1)

path.write_text(data, encoding='utf-8')
print('patched', path)
PY
sed -n '1,120p' ext/hash/hash_xxhash.c

